import{_ as o,o as a,c as t,a2 as c}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"內容搜尋","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/content-search.md","filePath":"zh-HK/user-guide/content-search.md","lastUpdated":1788568709000}'),r={name:"zh-HK/user-guide/content-search.md"};function d(s,e,n,l,i,h){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="內容搜尋" tabindex="-1">內容搜尋 <a class="header-anchor" href="#內容搜尋" aria-label="Permalink to &quot;內容搜尋&quot;">​</a></h1><p>內容搜尋外掛程式可以檢索本機文件中的內文，並在背景建立索引，與 Lertaro 原有的檔名搜尋並行運作。</p><h2 id="開始使用" tabindex="-1">開始使用 <a class="header-anchor" href="#開始使用" aria-label="Permalink to &quot;開始使用&quot;">​</a></h2><p>開啟<strong>設定 → 外掛模組 → 內容搜尋 → 設定</strong>，至少設定一個監控資料夾並儲存。預設觸發關鍵字為 <code>cs</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cs 專案計劃</span></span></code></pre></div><p>關鍵字後必須跟一個空格。如果 <code>cs</code> 與你的使用習慣衝突，可以在外掛模組設定中改成其他關鍵字。</p><h2 id="索引內容" tabindex="-1">索引內容 <a class="header-anchor" href="#索引內容" aria-label="Permalink to &quot;索引內容&quot;">​</a></h2><ul><li><strong>監控資料夾</strong>：外掛程式會向宿主索引服務註冊設定的本機資料夾，透過 SDK 的索引目錄列舉和經防抖處理的目錄變更通知完成首次及增量偵測；每個資料夾都必須由主機的本機磁碟機索引或資料夾索引涵蓋，否則列舉不到檔案。支援 <code>%USERPROFILE%</code> 等環境變數。</li><li><strong>檔案副檔名</strong>：預設包含 <code>txt</code>、<code>md</code>、<code>pdf</code>、<code>docx</code>、<code>docm</code>、<code>pptx</code>、<code>pptm</code>、<code>xlsx</code>、<code>xlsm</code> 和 <code>csv</code>，你可以按需要修改以逗號分隔的清單。</li><li><strong>PDF 檔案</strong>：會同時檢索可提取的頁面內文和已儲存的可填寫 PDF 表單欄位值。</li><li><strong>檔案大小</strong>：超過單一檔案大小上限的檔案會被跳過；內容索引還有獨立的體積上限，設為 <code>0</code> 表示不限制。</li><li><strong>排除路徑</strong>：輸入以分號分隔的正規表示式來排除相符的完整路徑。資料夾路徑相符時，其內容也會被排除。</li></ul><p>只有成功提取出內文的檔案才會參與搜尋。沒有對應文件提取器的二進位檔案會被跳過，不會作為亂碼文字寫入索引。</p><h2 id="搜尋方式" tabindex="-1">搜尋方式 <a class="header-anchor" href="#搜尋方式" aria-label="Permalink to &quot;搜尋方式&quot;">​</a></h2><p>在快速搜尋視窗中輸入 <code>cs</code>、空格和關鍵字即可搜尋。結果會顯示相符檔案的內文片段及所在資料夾，按下 <code>Enter</code> 可開啟選取的檔案。查詢有結果時，在未選取類型篩選的情況下，完整搜尋視窗中也會顯示這些檔案結果。</p><p>首次建立索引時，<code>cs</code> 佔位結果會顯示已索引檔案數和剩餘工作數。宿主監聽器報告新增或變更的目錄後，外掛程式會在背景處理其中的檔案，因此索引期間不會影響普通檔名搜尋；索引穩定後不會再循環掃描檔案系統。</p><h2 id="清除與重建" tabindex="-1">清除與重建 <a class="header-anchor" href="#清除與重建" aria-label="Permalink to &quot;清除與重建&quot;">​</a></h2><p>內容搜尋設定中提供兩個不同的操作：</p><ul><li><strong>清除索引</strong>：刪除內容索引，但不會重新掃描監控資料夾。</li><li><strong>重建索引</strong>：刪除內容索引，然後重新掃描所有監控資料夾。</li></ul><p>這兩個操作只影響內容搜尋索引，不會刪除 Lertaro 的普通檔名索引。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li>如果檔案沒有出現在結果中，請檢查它所在的資料夾、副檔名、排除規則和大小上限。</li><li>修改監控資料夾或索引規則後，請儲存設定並等待背景掃描完成。</li><li>修改規則後如果希望重新提取已有檔案，請使用<strong>重建索引</strong>。</li></ul>',18)])])}const g=o(r,[["render",d]]);export{u as __pageData,g as default};
